#!/usr/bin/env python3
# Gera manual.html: o manual de consulta da estratégia, com regras, gestão de categoria, marcas, produtos, preços, planogramas, comunicação e custo.
import json,re,html,pathlib,sys,time
R=pathlib.Path(__file__).resolve().parent.parent
sys.path.insert(0,str(R/'fonte'))
import plano_html as PH,novas as N
import calendario as CAL
r=PH.dados();cb=N.cat_base();rs=json.loads((R/'analise/marcas_alta.json').read_text())
import aulas as AU
br=N.br;I=lambda n:f'<svg class="ico"><use href="#i-{n.replace("i-","",1) if n.startswith("i-") else n}"/></svg>'
PAP={'Destino':dict(obj='Trazer a cliente à loja e dar lucro',lugar='Parede do fundo, conduz o fluxo',sort='Amplo nos itens que vendem, sem cauda',preco='Competitivo nos itens de referência',promo='Calendário e degustação de lançamento',kpi='Participação na venda, ruptura nos líderes, venda por módulo'),
'Rotina':dict(obj='Fazer voltar toda semana',lugar='Meio da loja, no caminho',sort='Núcleo estável, sem falta',preco='Constante e fácil de lembrar',promo='Encarte pontual',kpi='Frequência, itens por cupom, ruptura'),
'Ocasião':dict(obj='Aumentar a cesta e dar razão para vir',lugar='Ponta, mesa e áreas de destaque',sort='Curado, poucos e bem escolhidos',preco='Valor: paga pela escolha certa',promo='Datas do calendário',kpi='Empório na venda, cupons com empório, perda por validade'),
'Conveniência':dict(obj='Compra por impulso, no fim da visita',lugar='Caixa e pontos de passagem',sort='Pequeno formato, de alto giro',preco='Baixo desembolso',promo='Combos simples',kpi='Itens por cupom, giro do display')}
def pct(c): return br(N.pct(cb,c),1)+'%'
def faixa(c):
    k=N.BASEMAP.get(c,[None])[0]
    if c=='Empório': k='Empório: Chocolates e doces finos'
    if k not in cb: return 'sem base'
    return f'R$ {br(cb[k]["p25"])} a R$ {br(cb[k]["p75"])}'
def ficha(c):
    p=N.PAPEL[c];d=PAP[p];mods=[r[T]['modulos'].get(c,0) if c!='Caixa' else {'P':.5,'M':.5,'G':1}[T] for T in 'PMG'];sk=[r[T]['cats'].get(c,{}).get('skus','junto') for T in 'PMG']
    return f'''<article class="fi"><header><span class="mot" style="background:{N.COR[N.MOT[c]]}">{I(N.ICO[N.MOT[c]])}</span><div><h4>{html.escape(c)}</h4><small>Motor {N.MOT[c]} · papel {p} · {pct(c) if c!="Caixa" else "posição secundária"} da venda da rede</small></div></header>
<p class="ind">{html.escape(N.IND[c])}</p><dl><dt>Objetivo</dt><dd>{d["obj"]}</dd><dt>Lugar</dt><dd>{d["lugar"]}</dd><dt>Sortimento</dt><dd>{d["sort"]}</dd><dt>Preço</dt><dd>{d["preco"]}. Faixa: {faixa(c)}</dd><dt>Promoção</dt><dd>{d["promo"]}</dd><dt>Cartão de metas</dt><dd>{d["kpi"]}</dd><dt>Marcas que mais pesam</dt><dd>{html.escape(N.topm(cb,c)) or "por definição da loja"}</dd><dt>Módulos P, M, G</dt><dd>{" · ".join(N.n(float(m)) for m in mods)}</dd><dt>Produtos P, M, G</dt><dd>{" · ".join(str(s) for s in sk)}</dd></dl></article>'''
def rel(T,c):
    cc=r[T]['cats'][c];nuc=PH.classes(r,T,c);lin=PH.relatorio(cc,PH.fotos(),nuc)
    fil=''.join(f'<tr><td>{x["mod"]}.{x["niv"]}.{x["pos"]}</td><td>{x["sku"]}</td><td>{html.escape(x["nome"].title())}</td><td>{html.escape(x["marca"])}</td><td>{html.escape(x["sub"])}</td><td>{x["fr"]}</td><td>{x["cap"]}</td><td class="np">{PH._r(x["pmin"])} a {PH._r(x["pmax"])}</td><td class="np">{PH._r(x["pm"])}</td><td>{x["cl"]}</td></tr>' for x in lin)
    return f'<details class="re"><summary>Relatório de posições: {len(lin)} produtos</summary><table class="tb"><thead><tr><th>Pos.</th><th>SKU</th><th>Produto</th><th>Marca</th><th>Subcategoria</th><th>Frentes</th><th>Capacidade</th><th>Faixa de preço, R$</th><th>Médio pago, R$</th><th>Classe</th></tr></thead><tbody>{fil}</tbody></table></details>'
def plano_sec(T):
    h=''
    for c in N.ORD:
        if c not in r[T]['cats']: continue
        cc=r[T]['cats'][c]
        h+=f'<div class="pl" id="pl-{T}-{N.ORD.index(c)}"><h4>{html.escape(c)} <small>loja {T}</small></h4>{PH.plano(r,T,c,px=(4.0 if cc.get("f",1)<=2 else 3.4))}'
        h+=rel(T,c) if 'niveis' in cc else ''
        h+='</div>'
    return h
def tabela(cab,lin,cl='tb'):
    return f'<table class="{cl}"><thead><tr>'+''.join(f'<th>{c}</th>' for c in cab)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in l)+'</tr>' for l in lin)+'</tbody></table>'
def nucleo_tab():
    lin=[]
    for c in N.ORD:
        cc=r['P']['cats'].get(c)
        if not cc or 'niveis' not in cc: continue
        it=sorted([e for n in cc['niveis'] for m in n['mods'] for e in m],key=lambda e:-e['v'])[:8]
        for e in it: lin.append([html.escape(c),e['sku'],html.escape(e['desc'].title()),html.escape(e['mc']),'R$ '+br(e.get('pm',0),2) if e.get('pm') else ''])
    return tabela(['Categoria','SKU','Produto','Marca','Preço médio pago'],lin)
ALT=sorted(rs['emAltaRede'],key=lambda x:0) if isinstance(rs['emAltaRede'],list) else rs['emAltaRede']
def mercado_fontes():
    lin=[]
    for x in rs['emAltaMercado']['evidencias']:
        f=x.get('fonte') or {}
        lin.append([html.escape(str(x.get('categoria',''))),f'<b>{html.escape(str(x.get("marcaOuMovimento","")))}</b>',html.escape(str(x.get('evidencia',''))),html.escape(str(f.get('data',''))),f'<a href="{html.escape(f.get("url",""))}" target="_blank" rel="noopener">{html.escape(str(f.get("veiculo","abrir")))}</a>'])
    return tabela(['Categoria','Marca ou movimento','Evidência','Data','Fonte'],lin)
def recs():
    return tabela(['#','Marca ou tipo','Categoria','Motor','Situação','Venda na rede','Mercado','Decisão','Cuidado'],[[x['prioridade'],'<b>'+html.escape(x['marcaOuTipo'])+'</b>',html.escape(x['categoria']),html.escape(x['motor']),html.escape(x['situacao']),html.escape(x['dadoInterno']),html.escape(x['evidenciaExterna']),'<b>'+html.escape(x['acao'])+'</b>',html.escape(x['risco'])] for x in rs['recomendacoes']])
tab,bars,pay,tot=N.custo(r)
SEC=[('como','Como funciona','regras'),('regras','Regras da rede','escudo'),('gc','Gestão de categoria','grade'),('produtos','Produtos','pacote'),('marcas','Marcas','handshake'),('precos','Preços','tag'),('loja','Organização da loja','loja'),('plano','Planogramas P, M e G','gondola'),('cv','Comunicação visual','placa'),('custo','Custo e tempo por ponto','moeda'),('exec','Execução e auditoria','check'),('piloto','Piloto e acompanhamento','teste'),('conc','Para entender: os conceitos','aula'),('glos','Glossário','livro')]
nav=''.join(f'<a href="#{a}">{I(c)}<span>{i+1}. {b}</span></a>' for i,(a,b,c) in enumerate(SEC))
sub_pl=''.join(f'<a class="s" href="#plano{T}">Loja {T}</a>' for T in 'PMG')
corpo=f'''
<section id="como"><h2>1. Como funciona</h2>
<p class="lead">Este manual transforma o posicionamento da marca, <b>da nutrição ao estilo de vida</b>, em regra de loja. A rede decide uma vez; cada loja conta seus módulos, lê a sua ficha e monta.</p>
<h3>A receita em oito passos</h3><ol class="pas">
<li><b>Entender como ela escolhe.</b> Motivo, tipo, marca e preço, nessa ordem.</li><li><b>Dar um papel a cada categoria.</b> Destino, rotina, ocasião ou conveniência.</li><li><b>Saber que loja é esta.</b> Tamanho em módulos (P, M, G) e perfil (suplemento forte, equilibrado, granel forte).</li><li><b>Escolher os produtos.</b> Núcleo, lista aprovada e até 20% local.</li><li><b>Dividir o espaço.</b> Pela venda vezes o peso do papel, conferindo o que cabe.</li><li><b>Definir as frentes.</b> Para não faltar e para ser visto.</li><li><b>Montar pela regra.</b> A prateleira segue uma lógica só.</li><li><b>Conferir e ajustar.</b> Auditoria mensal e revisão trimestral.</li></ol>
<h3>Quem decide o quê</h3>{tabela(['Quem','Decide','Quando'],[['Comitê de curadoria (Francine, compras, 75 LAB)','Árvore, papéis, núcleo, lista aprovada, entrada e saída de marcas, calendário','Quinzenal'],['Rede','Regras dos passos 5 a 7, peças e frases permitidas','Uma vez, revisão trimestral'],['Franqueado','Até 20% regional, itens da lista aprovada, ações opcionais','Mensal, com registro'],['Equipe da loja','Reposição, etiqueta, auditoria com fotos','Diário e mensal']])}
<h3>Qual é a minha loja?</h3>{tabela(['Tamanho','Área','Módulos','Suplementos','Abastecer','Granel','Chás','Empório','Produtos'],[[f'<b>{T}</b>',PH.TAM[T] if hasattr(PH,"TAM") else N.TAMN[T],int(sum(r[T]["modulos"].values())),N.n(sum(v for k,v in r[T]["modulos"].items() if N.MOT.get(k)=="Cuidar")),N.n(sum(r[T]["modulos"].get(k,0) for k in ("Barras e snacks","Cafés funcionais","Despensa"))),N.n(r[T]["modulos"]["Granel"]),N.n(r[T]["modulos"]["Chás"]),N.n(r[T]["modulos"]["Empório"]),sum(v["skus"] for k,v in r[T]["cats"].items() if k!="Caixa")] for T in "PMG"])}
<p class="nota">Perfil equilibrado. Suplemento forte soma cerca de 10% aos módulos de suplemento; granel forte soma 1 módulo de granel. A loja acima de 120 m² segue a G e soma módulos pela mesma conta.</p></section>
<section id="regras"><h2>2. Regras da rede</h2><div class="dois"><div class="cx"><h3>{I('escudo')} Obrigatório em toda loja</h3><ul><li>Mesma árvore e mesmos nomes de categoria, setor e subcategoria.</li><li>Papel de cada categoria e sua posição: destino no fundo, rotina no meio, ocasião na ponta.</li><li>Módulo de 0,90 m como unidade de conta.</li><li>Uma subcategoria e um tamanho por prateleira, marca em bloco e líder no centro.</li><li>O que mais gira nos olhos, e o pesado sempre embaixo.</li><li>Núcleo igual em lojas do mesmo tamanho.</li><li>Etiqueta de 6,5 × 3,5 cm e peças da biblioteca.</li><li>Frases permitidas, sem promessa de cura ou de emagrecimento.</li><li>Calendário anual e auditoria mensal.</li></ul></div><div class="cx ol"><h3>{I('local')} Cada loja adapta</h3><ul><li>Até 20% para regionais e achados da franqueada, a começar do nível 1.</li><li>Até 20% da lista aprovada pela rede.</li><li>Tamanho de cada bloco, conforme os módulos.</li><li>Foco por perfil de loja.</li><li>Sequência física das paredes, conforme a planta.</li><li>Ações opcionais do calendário.</li></ul></div></div>
<h3>As oito regras da prateleira</h3><ol class="pas"><li><b>Um setor por gôndola, uma subcategoria por prateleira.</b></li><li><b>Nos olhos, o que mais gira.</b> Níveis 3 e 4, dentro do tamanho permitido naquela altura. O líder acima de 500 g vai para o nível 5.</li><li><b>Líder no centro do bloco.</b></li><li><b>Marca em bloco, dentro da prateleira.</b></li><li><b>Um tamanho por prateleira, pesado embaixo.</b> Dose até 100 g no alto, até 500 g no meio. Acima de 500 g, nos níveis 5 e 6.</li><li><b>Um produto, uma casa.</b> Ponto extra tem prazo, até 2 posições secundárias.</li><li><b>Faltou?</b> Etiqueta e 2 dias para repor. Depois, puxa o vizinho e registra.</li><li><b>Horizontal onde ela leva vários.</b> Granel e empório.</li></ol>
<h3>Frases</h3><div class="dois"><div class="cx"><b>Pode</b><p>“Tome com a refeição”, “Fonte de proteína”, “Azeite de um único produtor”, “Fale com a nossa equipe”.</p></div><div class="cx"><b>Não pode</b><p>Citar gripe, insônia, ansiedade, promessa de emagrecer, “previne” ou “trata”.</p></div></div></section>
<section id="gc"><h2>3. Gestão de categoria</h2><p class="lead">Cada categoria é um pequeno negócio: definir, dar papel, avaliar, cartão de metas, estratégia, táticas, implantar e revisar. Abaixo, a indicação de todas, seguida da ficha de cada uma.</p>
{N.categorias_tabela(r)}<h3>O manual de cada categoria</h3>{''.join(f'<article class="cmm" id="cat-{i}">{N.manual_cat(r,c,PH.fotos())}</article>' for i,c in enumerate(N.ORD))}
<h3>Tipos de loja: produtos por módulo</h3><p class="nota">Abra cada tipo para ver a lista módulo a módulo, com o nível, o SKU e as frentes. Esta lista é só de consulta aqui e no kit; não entra no PDF, por causa do tamanho.</p>{N.ficha12_manual()}</section>
<section id="produtos"><h2>4. Produtos</h2><h3>Filtro de curadoria: quatro perguntas para entrar</h3><ol class="pas"><li><b>Combina com quem se cuida?</b> Ingrediente, origem ou feitio que a cliente respeita.</li><li><b>Só existe bem na curadoria?</b> Não é o que ela já pega no mercado, ao mesmo preço.</li><li><b>Tem ocasião clara?</b> Receber, cozinhar, presentear ou o dia a dia.</li><li><b>A loja consegue operar?</b> Validade, equipamento, licença e giro.</li></ol>
<h3>Núcleo, lista e local</h3>{tabela(['Parte','Quanto','O que é','Quem decide'],[['<b>Núcleo</b>','60%','Igual em toda loja do mesmo tamanho. Faz a venda e a marca.','Rede'],['<b>Lista aprovada</b>','20%','A loja escolhe de uma lista da rede.','Loja, dentro da lista'],['<b>Local</b>','20%','Regional e achados da franqueada.','Franqueado, com registro']])}
<h3>Como entra e como sai</h3><div class="dois"><div class="cx"><b>Entra</b><p>Passa no filtro e tira alguém: entra um, sai um. Toda decisão fica para o ritual do mês, no comitê.</p></div><div class="cx"><b>Sai</b><p>Traz a cliente de volta? Completa a cesta? Tem substituto na loja? Três “não”: sai, sem queima, em até 90 dias.</p></div></div>
<h3>Lista-base do núcleo</h3><p class="nota">Os 8 primeiros de cada categoria na loja P, pela venda real. A lista completa está nos relatórios de posição e no kit.</p>{nucleo_tab()}<p class="nota">Por categoria, os três grupos estão na tela “O que entra em cada parte” da apresentação e nos relatórios de posição abaixo.</p></section>
<section id="marcas"><h2>5. Marcas</h2><h3>Decisão por marca</h3>{recs()}<p class="nota">Método: venda nas mesmas lojas, sem ajuste de preço; marca cruzada com o cadastro por nome e descrição. Sem comparação ano contra ano. Os números de empresa muitas vezes vêm da própria empresa.</p><h3>Evidências de mercado</h3>{mercado_fontes()}
<h3>Ressalvas</h3><ul>{''.join(f"<li>{html.escape(str(x))}</li>" for x in rs["ressalvas"] if not re.search("OZ.MPIC|GLP.?1 SUPPORT|Correção do briefing",str(x),re.I))}</ul></section>
<section id="precos"><h2>6. Preços</h2><p class="lead">Preço tem três trabalhos. A régua abaixo mostra em que faixa cada categoria vive hoje, com a venda real.</p>{tabela(['Papel','O que é','Regra','Trabalho'],[['<b>Referência</b>','Cerca de 50 produtos que a cliente compara: Crealift, Creafort, Supercoffee','Perto da farmácia e do mercado, com teto definido pela rede','Mostrar que a loja é justa'],['<b>Valor</b>','A maioria: encapsulados de conversa, ômegas específicos, empório','Preço com margem. A cliente paga pela escolha certa','Pagar a conta da loja'],['<b>Oportunidade</b>','Ofertas do calendário','Cada encarte traz 1 oferta de empório e 1 de granel','Criar motivo para vir hoje']])}<div style="margin-top:14px">{N.regua_precos()}</div><p class="nota">O teto de preço depende do custo por produto e da pesquisa de preços na farmácia e no mercado, dados ainda pedidos.</p></section>
<section id="loja"><h2>7. Organização da loja</h2><p class="lead">Destino no fundo, rotina no meio, ocasião na ponta e no centro, conveniência no caixa. A loja é organizada na ordem em que a cliente anda.</p>{tabela(['Zona','O que fica','Por quê'],[['<b>Entrada</b>','Vitrine e placa. Os primeiros passos não vendem','Zona de descompressão (Underhill, 1999)'],['<b>Rotina no caminho</b>','Barras, snacks e despensa','Fazem voltar toda semana'],['<b>Fundo</b>','Proteínas, creatina, colágeno, performance','O motivo da visita conduz o fluxo'],['<b>Laterais</b>','Vitaminas, ômegas, intestino, chás','Rotina consultiva'],['<b>Granel</b>','Parede de 20 a 40 tubos','Frequência semanal'],['<b>Centro</b>','Mesa do Empório, onde houver vão','Compra não planejada (Hui e outros, 2013)'],['<b>Caixa</b>','Pequeno formato','Conveniência e impulso']])}
{''.join(f'<h3>Loja {T}: {N.TAMN[T]}</h3><div class="lj-m">{N.planta_svg(T)}</div>' for T in 'PMG')}
<h3>Dividir o espaço, passo 5</h3><p>Módulos da loja × quanto a categoria vende × peso do papel (destino 1,2; rotina 1,0; ocasião 0,8; conveniência 0,7) = módulos da categoria. Depois confere se o que faz de 80% a 95% da venda cabe. Meio módulo é a menor unidade.</p>
<h3>Frentes, passo 6</h3><p><b>Frentes</b> = (venda por semana ÷ 7 × dias até a próxima entrega + 1 de segurança) ÷ unidades que cabem atrás de uma frente. Toda loja começa com 1 por produto; o líder do bloco ganha até 3. Sobrou espaço: entra o próximo produto da venda e, depois, frente para quem mais vende, até 2. Mais que isso, só em data ou com verba de marca.</p></section>
<section id="plano"><h2>8. Planogramas P, M e G</h2><p class="lead">Todos os planogramas da loja inteira, por categoria. Cada foto é uma frente. Cada planograma tem o relatório de posições: módulo.nível.posição, SKU, produto, marca, frentes e capacidade.</p><p class="nota">Versão 1, gerada pela venda real de cada faixa de loja e pelas regras acima. Largura estimada pelo peso e formato: a trena fecha. Capacidade: frentes × 6 unidades, a confirmar. Faixa de preço: do preço pago por loja e mês, de 25% a 90%, em final 0,90, e a calibrar com o custo por produto e a pesquisa de preços. Empório: traz o que a rede já vende; as novidades entram pela curadoria. Núcleo são os 60% de produtos que mais vendem em cada tamanho de loja, lista os 20% seguintes, e os últimos 20% a loja pode trocar por local.</p>
{''.join(f'<div id="plano{T}"><h3>Loja {T}: {N.TAMN[T]}, {int(sum(r[T]["modulos"].values()))} módulos</h3>{plano_sec(T)}</div>' for T in 'PMG')}</section>
<section id="cv"><h2>9. Comunicação visual</h2>{tabela(['Distância','Pergunta','Peças','Regra','P','M','G'],[['<b>Da rua</b>','Que loja é esta?','Vitrine e placa de entrada','Uma promessa por vez',1,1,1],['<b>8 m</b>','Onde está o que vim buscar?','Placas suspensas e testeiras','Palavra grande, sem foto','3 e 14','5 e 28','6 e 39'],['<b>4 m</b>','O que tem aqui?','Faixa de categoria','Parte alta do módulo',*(N.quant(r,T)["cat"] for T in "PMG")],['<b>2 m</b>','Qual é o meu?','Faixa de subcategoria e régua “para que serve”','Borda da prateleira',*(N.quant(r,T)["sub"] for T in "PMG")],['<b>Na mão</b>','Quanto custa e serve para mim?','Etiqueta e selo de benefício','Uma por produto',*(N.quant(r,T)["sku"] for T in "PMG")]])}
<h3>Biblioteca de peças</h3>{tabela(['Peça','Medida ou regra'],[['Testeira','Largura do módulo × 18 cm. Lê a 8 m'],['Faixa de categoria','Parte alta do módulo. Lê a 4 m'],['Faixa de subcategoria','Borda da prateleira. Lê a 2 m'],['Régua “para que serve”','Uso, dose e formato, em uma linha'],['Stopper','Máximo 1 por módulo, com data de saída'],['Etiqueta padrão','6,5 × 3,5 cm, já na marca'],['Benefício','Selos do atributo do cadastro'],['Lançamento','Faixa de 60 dias'],['Destaque','Produto do mês ou curadoria'],['Cross-selling','Receita ou par']])}
<p class="nota">Identidade: Posicionamento de Marca, p. 42 a 64. Temporárias sempre com data de saída no calendário. A indústria entra só com verba, dentro da mesma regra.</p><img class="ft" src="assets/img/novas/pecas-pdv.jpg" alt="Peças aplicadas em gôndola, simulação" loading="lazy"></section>
<section id="custo"><h2>10. Custo e tempo por ponto da loja</h2>{tab}<h3>Quanto tempo leva</h3>{tabela(['Por loja','P','M','G'],[['Instalar peças',*(N.n(round(N.horas(r,T)[0],0))+' h' for T in 'PMG')],['Remontar a gôndola, 1,5 h por módulo',*(N.n(round(N.horas(r,T)[1],0))+' h' for T in 'PMG')],['<b>Total, pessoa-hora</b>',*('<b>'+N.n(round(sum(N.horas(r,T)),0))+' h</b>' for T in 'PMG')],['Noites de 6 h, equipe de 3',*(N.n(round(sum(N.horas(r,T))/18+.49,0)) for T in 'PMG')]])}<p class="nota">Produção: até 30 dias úteis com a mesa, 15 sem ela. Estimativa a confirmar no piloto.</p><div style="margin-top:12px">{bars}</div><p class="nota">Estimativa de referência da 75 LAB, antes de cotação, para peças em baixa tiragem, sem frete, instalação e móveis de gôndola. Para pagar em 12 meses, com margem bruta de 35% (hipótese a trocar pela real), a venda nova por mês é de R$ {br(round(pay['P']/12/.35,-1))} na P, R$ {br(round(pay['M']/12/.35,-1))} na M e R$ {br(round(pay['G']/12/.35,-1))} na G.</p></section>
<section id="cal"><h3>Calendário de trade 2027</h3><p class="lead">Datas, papel de cada motor, participação real na venda e peso proposto do trade em cada mês. A participação real quase não muda ao longo do ano: o calendário escolhe onde pôr força em cada mês.</p>{CAL.manual()}<p class="nota">Participação: relatório de vendas de 11/2025 a 10/2026, com outubro parcial. Um único ano de base: indica tendência, não prova sazonalidade. Peso do trade: proposta da 75 LAB, em % das ativações de ponta, mesa e encarte. Datas de 2027 a integrar ao calendário oficial da rede.</p></section><section id="exec"><h2>11. Execução e auditoria</h2><h3>Como montar a loja</h3><ol class="pas"><li>Contar os módulos com a trena e achar a ficha P, M ou G.</li><li>Conferir a planta e marcar as zonas.</li><li>Tirar a gôndola por setor, limpar e ajustar as prateleiras.</li><li>Montar pelo planograma, do fundo para a frente, do nível 6 para o nível 1.</li><li>Aplicar etiquetas e faixas. Depois as testeiras e placas.</li><li>Fotografar: 6 fotos fixas por loja.</li><li>Registrar o que foi trocado por regional.</li></ol>
<h3>Auditoria mensal: 85% ou mais, loja no padrão</h3><ul><li>Cada categoria no lugar do planograma e subcategoria na prateleira certa.</li><li>Líderes nos olhos e com o número de frentes previsto.</li><li>Sem ruptura aberta há mais de 2 dias.</li><li>Etiqueta padrão em todos os produtos, sem cartaz fora da biblioteca.</li><li>Peças temporárias dentro do prazo.</li><li>Teste de achar: categoria de destino em até 10 segundos.</li></ul></section>
<section id="piloto"><h2>12. Piloto e acompanhamento</h2>{tabela(['Número da semana','Meta','Regra de leitura'],[['Empório na venda','6% (hoje 1,9%)','Vai para a rede com 6% ou mais'],['Venda por módulo de empório','R$ 4 mil por mês','Média de Pinheiros'],['Venda contra loja espelho','+3 pontos','Comparação com lojas parecidas'],['Auditoria','85%','Padrão mantido'],['Tempo para achar','Até 10 s','Teste com pessoa de fora']])}<p>Empório de 3% a 6%: muda produto e lugar, por mais 6 semanas. Abaixo de 3%, ou perda por validade acima de 5%: para e repensa, e a organização da loja continua. Pinheiros, com Moinhos como loja espelho, 12 semanas: loja organizada nas 6 primeiras, soma o empório nas 6 últimas. O escopo contempla 1 loja; se a rede quiser ampliar, Alphaville pode ser a segunda.</p></section>
<section id="conc"><h2>13. Para entender: os conceitos</h2><p class="lead">Os conceitos de marketing, varejo e gestão de categoria usados na estratégia, cada um com a explicação, o infográfico, a fonte e o que significa na Divina Terra.</p>{''.join(f'<article class="au-m"><h3>{a["tema"]}</h3><p class="au-d" style="font-size:19px;max-width:980px">{a["defi"]}</p><div style="margin:10px 0">{a["info"]}</div><div class="au-q"><b>{I("loja")} Na Divina Terra</b>{a["aqui"]}</div><p class="nota">Fonte: {a["fonte"]}</p></article>' for a in AU.A)}</section>
<section id="glos"><h2>14. Glossário</h2>{tabela(['Termo','O que quer dizer'],[['Módulo','Trecho de gôndola de 0,90 m de largura, com 6 níveis'],['Frente','Quantos produtos iguais ficam de frente para a cliente'],['Faixa de tamanho','Dose até 100 g, até 500 g e acima de 500 g. Uma faixa por prateleira'],['Capacidade','Quantas unidades cabem no lugar do produto'],['Testeira','Placa do alto do módulo'],['Planograma','Desenho de cada prateleira, com produto, posição e frentes'],['Núcleo','Produtos iguais em todas as lojas do mesmo tamanho'],['Papel','O trabalho da categoria: destino, rotina, ocasião ou conveniência'],['Ruptura','Produto em falta na prateleira'],['Giro','Quantas unidades vendem por semana'],['Loja espelho','Loja parecida, que não muda, usada para comparar']])}</section>'''
